module LifeguardPos(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input signed [7:0] x0, y0,\n    input signed [7:0] x1, y1,\n    input signed [7:0] x2, y2,\n    input signed [7:0] x3, y3,\n    input signed [7:0] x4, y4,\n    input signed [7:0] x5, y5,\n    input signed [7:0] x6, y6,\n    input signed [7:0] x7, y7,\n    output reg signed [15:0] A_x,\n    output reg signed [15:0] A_y,\n    output reg signed [15:0] B_x,\n    output reg signed [15:0] B_y,\n    output reg done\n);\n\n    // FSM States\n    localparam [2:0]\n        IDLE     = 3'd0,\n        LOAD     = 3'd1,\n        SORT     = 3'd2,\n        MED_CALC = 3'd3,\n        OUTPUT   = 3'd4;\n\n    reg [2:0] state, next_state;\n    reg [3:0] n_reg;\n    reg signed [7:0] xs [0:7];\n    reg [2:0] stage_cnt;\n    reg signed [15:0] median;\n\n    // Sorting stages\n    reg signed [7:0] next_xs [0:7];\n    integer i;\n\n    // FSM State Register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            A_x <= 16'd0;\n            A_y <= 16'd0;\n            B_x <= 16'd0;\n            B_y <= 16'd0;\n            n_reg <= 4'd0;\n            for (i=0; i<8; i=i+1) xs[i] <= 8'd0;\n            stage_cnt <= 3'd0;\n        end else begin\n            state <= next_state;\n            if (state == SORT) begin\n                stage_cnt <= stage_cnt + 3'd1;\n                for (i=0; i<8; i=i+1) xs[i] <= next_xs[i];\n            end\n            case (state)\n                LOAD: begin\n                    n_reg <= n;\n                    xs[0] <= (0 < n) ? x0 : 8'sh7F;\n                    xs[1] <= (1 < n) ? x1 : 8'sh7F;\n                    xs[2] <= (2 < n) ? x2 : 8'sh7F;\n                    xs[3] <= (3 < n) ? x3 : 8'sh7F;\n                    xs[4] <= (4 < n) ? x4 : 8'sh7F;\n                    xs[5] <= (5 < n) ? x5 : 8'sh7F;\n                    xs[6] <= (6 < n) ? x6 : 8'sh7F;\n                    xs[7] <= (7 < n) ? x7 : 8'sh7F;\n                    stage_cnt <= 3'd0;\n                end\n                MED_CALC: begin\n                    if (n_reg[0]) begin // odd\n                        automatic int idx = (n_reg - 1) >> 1;\n                        median <= { {8{xs[idx][7]}}, xs[idx] };\n                    end else begin // even\n                        automatic int idx1 = (n_reg >> 1) - 1;\n                        automatic int idx2 = (n_reg >> 1);\n                        automatic signed [15:0] sum = { {8{xs[idx1][7]}}, xs[idx1] } + { {8{xs[idx2][7]}}, xs[idx2] };\n                        median <= sum >>> 1;\n                    end\n                end\n                OUTPUT: begin\n                    A_x <= median - 16'sd100;\n                    A_y <= 16'sd0;\n                    B_x <= median + 16'sd100;\n                    B_y <= 16'sd0;\n                    done <= 1'b1;\n                end\n                default: done <= 1'b0;\n            endcase\n        end\n    end\n\n    // Next state logic\n    always @* begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = LOAD;\n            LOAD: next_state = SORT;\n            SORT: if (stage_cnt == 3'd5) next_state = MED_CALC;\n            MED_CALC: next_state = OUTPUT;\n            OUTPUT: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Sort combinational logic\n    always @* begin\n        for (i=0; i<8; i=i+1) next_xs[i] = xs[i];\n        if (state == SORT) begin\n            case (stage_cnt)\n                3'd0: begin\n                    if (xs[0] > xs[1]) {next_xs[0], next_xs[1]} = {xs[1], xs[0]};\n                    if (xs[2] > xs[3]) {next_xs[2], next_xs[3]} = {xs[3], xs[2]};\n                    if (xs[4] > xs[5]) {next_xs[4], next_xs[5]} = {xs[5], xs[4]};\n                    if (xs[6] > xs[7]) {next_xs[6], next_xs[7]} = {xs[7], xs[6]};\n                end\n                3'd1: begin\n                    if (xs[0] > xs[2]) {next_xs[0], next_xs[2]} = {xs[2], xs[0]};\n                    if (xs[1] > xs[3]) {next_xs[1], next_xs[3]} = {xs[3], xs[1]};\n                    if (xs[4] > xs[6]) {next_xs[4], next_xs[6]} = {xs[6], xs[4]};\n                    if (xs[5] > xs[7]) {next_xs[5], next_xs[7]} = {xs[7], xs[5]};\n                end\n                3'd2: begin\n                    if (xs[1] > xs[2]) {next_xs[1], next_xs[2]} = {xs[2], xs[1]};\n                    if (xs[5] > xs[6]) {next_xs[5], next_xs[6]} = {xs[6], xs[5]};\n                    if (xs[0] > xs[4]) {next_xs[0], next_xs[4]} = {xs[4], xs[0]};\n                    if (xs[3] > xs[7]) {next_xs[3], next_xs[7]} = {xs[7], xs[3]};\n                end\n                3'd3: begin\n                    if (xs[1] > xs[5]) {next_xs[1], next_xs[5]} = {xs[5], xs[1]};\n                    if (xs[2] > xs[6]) {next_xs[2], next_xs[6]} = {xs[6], xs[2]};\n                end\n                3'd4: begin\n                    if (xs[1] > xs[4]) {next_xs[1], next_xs[4]} = {xs[4], xs[1]};\n                    if (xs[3] > xs[6]) {next_xs[3], next_xs[6]} = {xs[6], xs[3]};\n                end\n                3'd5: begin\n                    if (xs[2] > xs[4]) {next_xs[2], next_xs[4]} = {xs[4], xs[2]};\n                    if (xs[3] > xs[5]) {next_xs[3], next_xs[5]} = {xs[5], xs[3]};\n                end\n                default: ;\n            endcase\n        end\n    end\n\nendmodule